-- ─────────────────────────────────────────────────────────────────────────────
-- V1__create_events_table.sql
--
-- Core events table.  This is the durable event queue.
-- Workers SELECT … FOR UPDATE SKIP LOCKED on this table to claim work safely.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TYPE event_status AS ENUM (
    'PENDING',
    'PROCESSING',
    'COMPLETED',
    'FAILED',
    'DLQ'
);

CREATE TYPE event_priority AS ENUM (
    'LOW',
    'NORMAL',
    'HIGH'
);

CREATE TABLE events (
    -- Surrogate primary key: UUID v4 generated by the database for uniqueness
    -- without coordination between application nodes.
    id                  UUID            NOT NULL DEFAULT gen_random_uuid(),

    -- Caller-supplied idempotency key.  Duplicate submissions with the same key
    -- are rejected (409 Conflict) and the original event ID is returned.
    idempotency_key     VARCHAR(255)    NOT NULL,

    -- Human-readable classification of what kind of event this is
    -- (e.g. "ORDER_PLACED", "PAYMENT_PROCESSED").
    event_type          VARCHAR(100)    NOT NULL,

    -- Arbitrary JSON payload supplied by the caller.
    -- JSONB: stored in binary form, supports indexing and JSON operators.
    payload             JSONB           NOT NULL,

    -- Processing priority — workers should prefer HIGH > NORMAL > LOW.
    priority            event_priority  NOT NULL DEFAULT 'NORMAL',

    -- Lifecycle state machine managed by workers and the retry/DLQ service.
    status              event_status    NOT NULL DEFAULT 'PENDING',

    -- Retry accounting
    attempt_count       SMALLINT        NOT NULL DEFAULT 0,
    max_attempts        SMALLINT        NOT NULL DEFAULT 5,

    -- Exponential-backoff: worker will not pick up the event before this time.
    -- NULL means "eligible for immediate processing".
    next_attempt_at     TIMESTAMPTZ,

    -- Last recorded failure reason for audit / debugging.
    last_failure_reason TEXT,

    -- Timestamps (all stored with timezone)
    created_at          TIMESTAMPTZ     NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ     NOT NULL DEFAULT now(),

    CONSTRAINT pk_events PRIMARY KEY (id),
    CONSTRAINT uq_events_idempotency_key UNIQUE (idempotency_key)
);

-- ── Indexes ────────────────────────────────────────────────────────────────

-- Workers query: WHERE status = 'PENDING' AND next_attempt_at <= now()
-- ORDER BY priority DESC, created_at ASC
CREATE INDEX idx_events_status_next_attempt
    ON events (status, next_attempt_at)
    WHERE status IN ('PENDING', 'FAILED');

-- Lookups by idempotency key (covered by the unique constraint, but named
-- explicitly here for documentation clarity)
CREATE INDEX idx_events_idempotency_key
    ON events (idempotency_key);

-- Filter / sort by priority within PENDING events
CREATE INDEX idx_events_priority_created
    ON events (priority DESC, created_at ASC)
    WHERE status = 'PENDING';
